import jakarta.persistence.EntityManager;
import jakarta.persistence.Lock;
import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.EntityGraph;
import org.springframework.transaction.annotation.Transactional;
class AccountRepository { EntityManager em; @EntityGraph(attributePaths={"owner"}) @Transactional @Lock(LockModeType.PESSIMISTIC_WRITE) void load() { em.createQuery("select a from Account a"); } }

